from pathlib import Path
from datetime import datetime,timezone
import json
root=Path(__file__).resolve().parent
read=lambda name:json.loads((root/name).read_text(encoding='utf-8'))
results=read('results.json')
v=read('evidence/PHOTO-006-independent-verification.json')
assert v['photo_and_paint_are_distinct_history_steps'] and v['unsaved_draft_undo_cancels_without_consuming_document_undo'] and all(r['complete_expected_document'] and r['full_size_rgba_exact'] for r in v['rows'])
results['cases']['PHOTO-006']=dict(status='Pass',variants_executed='Natural photo with saved Exposure 1/Brightness 7 and separate green paint layer. Done saves Brightness 25; real red marker drag on the other layer. Undo paint then photo; keyboard Redo both. New unsaved -100 Brightness draft; Ctrl+Z cancels it; subsequent ordinary Undo/Redo still changes only the paint mark.',criteria_observations='Every history stage restores its exact complete expected content and full-size RGBA. The 12763-pixel red mark is on the separate layer; the original photo pixels and recipe remain separate. The photo step changes only its recipe. Cancelling an unsaved draft with Undo leaves the document history intact. Actual active-layer selection is recorded separately, with no content fields excluded.',independent_oracle='Pillow 12.3.0 full RGBA, complete parsed project identities, independent layer PNG masks/coordinates and red colour dominance',evidence_paths='evidence/PHOTO-006-independent-verification.json; evidence/PHOTO-006-before.retropaint; evidence/PHOTO-006-photo-step.retropaint; evidence/PHOTO-006-paint-step.retropaint; evidence/PHOTO-006-undo-paint.retropaint; evidence/PHOTO-006-undo-photo.retropaint; evidence/PHOTO-006-redo-photo.retropaint; evidence/PHOTO-006-redo-paint.retropaint; evidence/PHOTO-006-unsaved-draft-ui.jpg; evidence/PHOTO-006-draft-undo-cancelled.retropaint; evidence/PHOTO-006-undo-after-draft.retropaint; evidence/PHOTO-006-redo-after-draft.retropaint; ui-events-current.jsonl',defect_or_blocker='None. A timed-out baseline capture was inspected and its missing PNG was actually redownloaded before testing resumed; no missing-byte attempt was passed.')
v=read('evidence/PHOTO-007-independent-verification.json')
assert all(v[k] for k in ['single_brightness_reset_only','visible_values_equal_saved_recipe','originals_neighbour_and_unrelated_fields_exact','actual_fresh_project_reopen_full_json_and_rgba_exact'])
results['cases']['PHOTO-007']=dict(status='Pass',variants_executed='Saved photo and distinct neighbouring sheet. Set non-default Exposure/Brightness/Contrast and Colour saturation/vibrance/hue. Reset only Light basic group. Reopen, set three Light values and double-click Brightness only. Actual downloaded project fresh production reopen/resave and inspection of both groups.',criteria_observations='Light group reset returns all three Light values to 0 while Colour remains -100/100/45. Individual Brightness double-click returns only Brightness to 0, retaining Exposure 1, Contrast 30 and all Colour values. Visible controls equal the saved recipe. Original pixels, neighbour and unrelated fields are exact; actual fresh reopened full JSON and rendered RGBA are exact.',independent_oracle='Pillow 12.3.0 full RGBA and complete parsed document comparisons; literal expected values matched against actual UI accessibility snapshots',evidence_paths='evidence/PHOTO-007-independent-verification.json; evidence/PHOTO-007-light-after-group-reset.txt; evidence/PHOTO-007-colour-after-other-group-reset.txt; evidence/PHOTO-007-after-single-reset.txt; evidence/PHOTO-007-colour-after-single-reset.txt; evidence/PHOTO-007-group-reset.retropaint; evidence/PHOTO-007-single-reset.retropaint; evidence/PHOTO-007-reopened.retropaint; evidence/PHOTO-007-reopened-light.txt; evidence/PHOTO-007-reopened-colour.txt; ui-events-current.jsonl',defect_or_blocker='This case certifies reset scope. It does not certify every scalar effect or endpoint; those remain separately recorded in the variant ledger.')
results['updated_at']=datetime.now(timezone.utc).isoformat()
(root/'results.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print('Recorded independently verified PHOTO-006 and PHOTO-007.')
